// TTA: original calendar and personal knowledge workspace.
let calendarCursor=new Date(),selectedDay=localISO(new Date()),knowledgeSearch='';
function localISO(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function atNoon(iso){return new Date(iso+'T12:00:00')}
function tta(){state.almanac??={events:[],notes:[],tasks:[],calendar:12,commandHistory:[]};return state.almanac}
function ttaLogo(){return '<span class="ttalogo" aria-hidden="true">☼<span>TTA</span></span>'}
function customDate(iso,count){let d=atNoon(iso),year=d.getFullYear(),start=Date.UTC(year,0,1),ordinal=Math.floor((Date.UTC(year,d.getMonth(),d.getDate())-start)/86400000),days=(Date.UTC(year+1,0,1)-start)/86400000;let month=Math.min(count-1,Math.floor(ordinal*count/days));let first=Math.ceil(month*days/count);return {year,month:month+1,day:ordinal-first+1,days,ordinal:ordinal+1}}
function calendarName(n){return n===12?'Gregorian · 12 months':n===13?'Magi Cicada · 13 months':n===17?'Magi Cicada · 17 months':n===21?'Blackjack · 21 months':`My calendar · ${n} months`}
function almanac(){const a=tta(),now=new Date(),today=localISO(now),dayEvents=a.events.filter(e=>e.date===selectedDay),openTasks=a.tasks.filter(t=>!t.done),custom=customDate(selectedDay,a.calendar),todayLabel=now.toLocaleDateString(appLocale(),{weekday:'long',month:'long',day:'numeric',year:'numeric'});return `<section class="ttahero"><div class="ttatop">${ttaLogo()}<div><div class="eyebrow">THE TABOR ALMANAC</div><small>ABOVE · MIDDLE · BELOW</small></div><span class="edition">YOUR PERSONAL EDITION</span></div><h1>Control your DAY.<br><em>Shape your TORMO’rrow.</em></h1><p>${todayLabel} · ${Intl.DateTimeFormat().resolvedOptions().timeZone}</p><div class="ttamotto">Don’t Delay — Start Today.</div></section><form id="commandForm" class="commandbar"><span aria-hidden="true">✦</span><input id="ttaCommand" name="command" required maxlength="500" aria-label="Tell the Almanac what you want" placeholder="Tell me what you want to organize…"><button>Do it ↗</button></form><div class="commandexamples">Try: <button data-command="Add dinner tomorrow at 7pm">Dinner tomorrow at 7pm</button><button data-command="Task: plan a weekend away">Add a task</button><button data-command="Note: Intimacy is respect">Save a thought</button><button data-command="Show 13 month calendar">13-month calendar</button><button data-command="Help">What can I say?</button></div><div id="commandResult" role="status" class="statusline">Commands organize your local planner and library. They do not book, message or perform external actions.</div><div class="stats"><div class="stat"><strong>${a.events.filter(e=>e.date===today).length}</strong><span>Plans today</span></div><div class="stat"><strong>${openTasks.length}</strong><span>Open tasks</span></div><div class="stat"><strong>${a.notes.length}</strong><span>Library entries</span></div></div><div class="grid two"><section class="card calendarcard"><div class="row"><h2 style="margin:0">Your calendars</h2><button class="subtle" id="ttaToday">Today</button></div><div class="toolbar"><select id="calendarMode" aria-label="Calendar system">${options([12,13,17,21].map(n=>String(n)),String(a.calendar))}${![12,13,17,21].includes(a.calendar)?`<option selected>${a.calendar}</option>`:''}</select><button id="customCalendar" class="outline">+ Custom</button></div><div class="calendarheading"><button class="quiet" data-month-step="-1" aria-label="Previous month">←</button><strong>${calendarCursor.toLocaleDateString(appLocale(),{month:'long',year:'numeric'})}</strong><button class="quiet" data-month-step="1" aria-label="Next month">→</button></div><div class="calendargrid">${['S','M','T','W','T','F','S'].map(d=>`<span class="weekday">${d}</span>`).join('')}${calendarCells()}</div><div class="calendarconversion"><strong>${calendarName(a.calendar)}</strong><p>${a.calendar===12?atNoon(selectedDay).toLocaleDateString(appLocale(),{dateStyle:'full'}):`Year ${custom.year} · Month ${custom.month} · Day ${custom.day}`}</p><small>Day ${custom.ordinal} of ${custom.days} · selected date ${selectedDay}</small></div>${a.calendar!==12?'<p class="statusline">Custom TTA view: divides the Gregorian year into nearly equal periods beginning January 1. “Magi Cicada” and “Blackjack” are your named concepts, not established historical calendar conversions.</p>':''}</section><section class="card"><div class="sectionhead" style="margin-top:0"><div><h2>Your day, at a glance</h2><p>${atNoon(selectedDay).toLocaleDateString(appLocale(),{dateStyle:'full'})}</p></div><button class="outline" id="addPlan">+ Plan</button></div>${dayEvents.length?dayEvents.sort((x,y)=>(x.time||'').localeCompare(y.time||'')).map(e=>`<div class="planrow"><span class="plantime">${esc(e.time||'Anytime')}</span><div><strong>${esc(e.title)}</strong><small>${esc(e.notes||'Your personal plan')}</small></div><button class="subtle" data-edit-plan="${e.id}" aria-label="Edit ${esc(e.title)}">Edit</button></div>`).join(''):empty('A little room to breathe. Add a plan or tell the command box what you have in mind.')}<div class="sectionhead"><h2>Things to do</h2><button id="addTask" class="subtle">+ Task</button></div>${a.tasks.map(t=>`<div class="taskrow"><label><input type="checkbox" data-task="${t.id}" ${t.done?'checked':''}><span class="${t.done?'done':''}">${esc(t.title)}</span></label><button class="subtle danger" data-delete-task="${t.id}" aria-label="Delete ${esc(t.title)}">×</button></div>`).join('')||'<p class="muted">No tasks yet. One thought, one next step.</p>'}</section></div><div class="sectionhead"><div><h2>A library for your whole world.</h2><p>Ancient ideas. Modern knowledge. Your own observations.</p></div><button data-page="knowledge" class="subtle">Open TORMO ↗</button></div><div class="grid">${[['Above','Ideas, meaning & the bigger picture','✧'],['Middle','People, relationships & daily living','♡'],['Below','Nature, materials & practical foundations','♧']].map(([h,t,i])=>`<button class="card ttacategory" data-knowledge-layer="${h}"><span>${i}</span><h3>${h}</h3><p>${t}</p></button>`).join('')}</div><p class="statusline">Original TTA identity and layout. Not affiliated with Farmers’ Almanac or The Old Farmer’s Almanac. Your data remains browser-local.</p>`}
function calendarCells(){const a=tta(),year=calendarCursor.getFullYear(),month=calendarCursor.getMonth(),first=new Date(year,month,1).getDay(),last=new Date(year,month+1,0).getDate();return '<span></span>'.repeat(first)+Array.from({length:last},(_,idx)=>{const d=idx+1,iso=localISO(new Date(year,month,d)),count=a.events.filter(e=>e.date===iso).length;return `<button data-day="${iso}" class="calday ${selectedDay===iso?'selected':''} ${iso===localISO(new Date())?'today':''}" aria-label="${iso}${count?', '+count+' plans':''}" aria-pressed="${selectedDay===iso}">${d}${count?'<i></i>':''}</button>`}).join('')}
const shelves=[['101','General knowledge'],['201','Thought & philosophy'],['301','Beliefs & traditions'],['401','People & society'],['501','Language & expression'],['601','Nature & science'],['701','Making & technology'],['801','Arts & literature'],['901','Places & history']];
let knowledgeLayer='All';
function knowledge(){const a=tta(),notes=a.notes.filter(n=>(knowledgeLayer==='All'||n.layer===knowledgeLayer)&&(!knowledgeSearch||[n.title,n.text,n.source,n.attributes,n.function,n.shelf].join(' ').toLowerCase().includes(knowledgeSearch.toLowerCase())));return title('THE TABOR ALMANAC · TORMO','Keep the meaning. Make it yours.','The Original Root Meanings Only — your workspace for attributes, characteristics and functions. Preserve source context alongside your interpretation.')+`<div class="toolbar"><div class="search"><input id="knowledgeSearch" placeholder="Search your library…" value="${esc(knowledgeSearch)}" aria-label="Search TORMO library"></div><button id="addNote">+ Library entry</button></div><div class="tabs">${['All','Above','Middle','Below'].map(l=>`<button class="chip ${knowledgeLayer===l?'active':''}" data-knowledge-layer="${l}">${l}</button>`).join('')}</div><div class="shelfgrid">${shelves.map(([n,l])=>`<button class="shelf" data-shelf="${n}"><b>${n}</b><span>${l}</span></button>`).join('')}</div><div class="note">TTA’s 101–901 shelves are a custom arrangement inspired by library organization, not official Dewey classes. Decimal and base-12 identifiers are provided separately; your sources and interpretations remain distinct.</div><div class="grid two">${notes.map(n=>`<article class="card"><div class="tags"><span class="tag">${esc(n.shelf||'101')}</span><span class="tag">${esc(n.layer||'Middle')}</span><span class="tag">${esc(n.polarity||'Neutral')}</span><span class="tag">${esc(n.mode||'Literal')}</span></div><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p>${n.attributes?`<p><b>Attributes:</b> ${esc(n.attributes)}</p>`:''}${n.function?`<p><b>Function:</b> ${esc(n.function)}</p>`:''}${n.source?`<p><b>Source / context:</b> ${esc(n.source)}</p>`:''}<small>Decimal ${Number(n.shelf||101)} · Base 12 ${Number(n.shelf||101).toString(12).toUpperCase()} (A=10, B=11)</small><button class="subtle" data-edit-note="${n.id}">Edit entry ↗</button></article>`).join('')||empty('Your library is ready for your first idea. Add an entry or say “Note: …” in the Almanac.')}</div>`}
function noteEditor(id,shelf='101'){const n=tta().notes.find(n=>n.id===id)||{};modal(`<h2>${id?'Edit your entry':'Add to your library'}</h2><form id="noteForm" data-id="${esc(id||'')}"><label>Title<input name="title" maxlength="150" required value="${esc(n.title||'')}"></label><label>Meaning, observation or idea<textarea name="text" maxlength="4000" required>${esc(n.text||'')}</textarea></label><div class="formgrid"><label>Shelf<select name="shelf">${shelves.map(([v,l])=>`<option value="${v}" ${(n.shelf||shelf)===v?'selected':''}>${v} · ${l}</option>`).join('')}</select></label><label>Layer<select name="layer">${options(['Above','Middle','Below'],n.layer||(knowledgeLayer==='All'?'Middle':knowledgeLayer))}</select></label><label>Interpretation<select name="mode">${options(['Literal','Figurative','Mythological'],n.mode||'Literal')}</select></label><label>Perspective<select name="polarity">${options(['Positive','Negative','Neutral'],n.polarity||'Neutral')}</select></label></div><label>Attributes & characteristics<textarea name="attributes" maxlength="1200">${esc(n.attributes||'')}</textarea></label><label>Function / what it does<input name="function" maxlength="500" value="${esc(n.function||'')}"></label><label>Source & original context<input name="source" maxlength="1000" value="${esc(n.source||'')}" placeholder="Author, link, tradition, or your own observation"></label><button>Save entry</button></form>${id?`<button class="subtle danger" data-delete-note="${id}">Delete entry</button>`:''}`)}
function planEditor(id){const e=tta().events.find(e=>e.id===id)||{};modal(`<h2>${id?'Edit your plan':'Make a plan'}</h2><form id="planForm" data-id="${esc(id||'')}"><label>Title<input name="title" maxlength="150" required value="${esc(e.title||'')}"></label><div class="formgrid"><label>Date<input type="date" required name="date" value="${esc(e.date||selectedDay)}"></label><label>Time · optional<input type="time" name="time" value="${esc(e.time||'')}"></label></div><label>Notes<textarea name="notes" maxlength="1500">${esc(e.notes||'')}</textarea></label><button>Save plan</button></form>${id?`<button class="subtle danger" data-delete-plan="${id}">Delete plan</button>`:''}`)}
function commandResult(message){if($('#commandResult'))$('#commandResult').textContent=message;toast(message)}
function runCommand(raw){const a=tta(),text=raw.trim(),lower=text.toLowerCase();if(!text)return;
 if(/^(help|what can)/i.test(text)){modal('<h2>Tell TTA what to organize.</h2><p>Try these commands in everyday words:</p><ul><li>Add dinner tomorrow at 7pm</li><li>Add coffee on 2026-11-12 at 09:30</li><li>Task: plan a weekend away</li><li>Note: Intimacy is respect</li><li>Show 17 month calendar</li><li>Find leather</li><li>Open my profile</li></ul><p>Local command shortcuts organize plans, tasks, notes and navigation. They do not use an AI service or perform bookings, messages or other external actions. For anything else, use the edit forms.</p>');return}
 let m=text.match(/(?:show|use|switch to)\s+(?:a\s+)?(\d+)\s*[- ]?month/i);if(m){const n=Number(m[1]);if(n<1||n>60){commandResult('Choose a calendar with 1 to 60 periods.');return}a.calendar=n;persist();render();commandResult(`Showing ${calendarName(n)}.`);return}
 if(/^(task|todo|to-do)(:|\s)/i.test(text)){let title=text.replace(/^(task|todo|to-do)[:\s]+/i,'').trim();if(!title)return;a.tasks.push({id:crypto.randomUUID(),title,done:false});persist();render();commandResult('Added your task.');return}
 if(/^(note|remember)(:|\s)/i.test(text)){let content=text.replace(/^(note|remember)[:\s]+/i,'').trim();if(!content)return;a.notes.push({id:crypto.randomUUID(),title:content.slice(0,90),text:content,shelf:'101',layer:'Middle',mode:'Literal',polarity:'Neutral',source:'My own note'});persist();render();commandResult('Saved to your TORMO library.');return}
 if(/^(find|search)(:|\s)/i.test(text)){query=text.replace(/^(find|search)[:\s]+/i,'');category='All';prefFilter='All preferences';go('interests');return}
 const routes={'my profile':'profile','profile':'profile','library':'knowledge','my buttons':'board','privacy':'settings','calendar':'almanac','almanac':'almanac','discover':'discover'};for(const [name,route] of Object.entries(routes)){if(lower==='open '+name){go(route);return}}
 if(/^(add|plan|schedule)\s/i.test(text)){let date=localISO(new Date()),match=text.match(/\b(\d{4}-\d{2}-\d{2})\b/);if(match){if(Number.isNaN(atNoon(match[1]).getTime())||localISO(atNoon(match[1]))!==match[1]){commandResult('Please use a valid date such as 2026-11-12.');return}date=match[1]}else if(/\btomorrow\b/i.test(text)){let d=new Date();d.setDate(d.getDate()+1);date=localISO(d)}else if(!/\btoday\b/i.test(text)){commandResult('Include today, tomorrow or a date like 2026-11-12, or use + Plan.');return}
 let time='',tm=text.match(/\bat\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b/i);if(tm){let h=Number(tm[1]),min=Number(tm[2]||0),ap=tm[3]?.toLowerCase();if(min>59||(!ap&&h>23)||(ap&&(h<1||h>12))){commandResult('Please use a valid time, such as 7pm or 19:00.');return}if(ap)h=h%12+(ap==='pm'?12:0);time=String(h).padStart(2,'0')+':'+String(min).padStart(2,'0')}
 let title=text.replace(/^(add|plan|schedule)\s+/i,'').replace(/\b(today|tomorrow)\b/ig,'').replace(/\b(?:on\s+)?\d{4}-\d{2}-\d{2}\b/,'');if(tm)title=title.replace(tm[0],'');title=title.trim();if(!title){commandResult('Give your plan a title.');return}a.events.push({id:crypto.randomUUID(),title,date,time,notes:''});selectedDay=date;calendarCursor=atNoon(date);persist();render();commandResult(`Added ${title} · ${date}${time?' at '+time:''}. No invitation sent.`);return}
 commandResult('Try “Add dinner tomorrow at 7pm”, “Task: …”, “Note: …”, or “Help”.');}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.monthStep){calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+Number(b.dataset.monthStep),1);render()}if(b.dataset.day){selectedDay=b.dataset.day;render()}if(b.id==='ttaToday'){calendarCursor=new Date();selectedDay=localISO(new Date());render()}if(b.id==='addPlan')planEditor();if(b.dataset.editPlan)planEditor(b.dataset.editPlan);if(b.id==='addNote')noteEditor();if(b.dataset.editNote)noteEditor(b.dataset.editNote);if(b.dataset.shelf)noteEditor(null,b.dataset.shelf);if(b.dataset.knowledgeLayer){knowledgeLayer=b.dataset.knowledgeLayer;go('knowledge')}if(b.dataset.command){$('#ttaCommand').value=b.dataset.command;$('#ttaCommand').focus()}if(b.id==='customCalendar')modal('<h2>Your own calendar.</h2><p>Choose how many nearly equal periods divide the Gregorian year. This is a personal organization system.</p><form id="calendarForm"><label>Periods per year<input name="count" type="number" min="1" max="60" required value="13"></label><button>Use this calendar</button></form>');if(b.id==='addTask')modal('<h2>One next step.</h2><form id="taskForm"><label>Task<input name="title" maxlength="250" required></label><button>Add task</button></form>');if(b.dataset.deleteTask){tta().tasks=tta().tasks.filter(t=>t.id!==b.dataset.deleteTask);persist();render()}if(b.dataset.deleteNote||b.dataset.deletePlan){const isNote=!!b.dataset.deleteNote,id=b.dataset.deleteNote||b.dataset.deletePlan;modal(`<h2>Delete this ${isNote?'entry':'plan'}?</h2><p>This removes it from your personal workspace.</p><button data-confirm-tta-delete="${id}" data-kind="${isNote?'notes':'events'}">Delete</button>`)}if(b.dataset.confirmTtaDelete){let a=tta();a[b.dataset.kind]=a[b.dataset.kind].filter(x=>x.id!==b.dataset.confirmTtaDelete);$('#modal').close();persist();render()}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='calendarMode'){tta().calendar=Number(t.value);persist();render()}if(t.dataset.task){let task=tta().tasks.find(x=>x.id===t.dataset.task);if(task)task.done=t.checked;persist();render()}});
document.addEventListener('input',e=>{if(e.target.id==='knowledgeSearch'){let start=e.target.selectionStart;knowledgeSearch=e.target.value;$('#main').innerHTML=knowledge();let input=$('#knowledgeSearch');input.focus();input.setSelectionRange(start,start)}});
document.addEventListener('submit',e=>{let f=e.target;if(!['commandForm','calendarForm','taskForm','noteForm','planForm'].includes(f.id))return;e.preventDefault();let v=Object.fromEntries(new FormData(f)),a=tta();if(f.id==='commandForm'){runCommand(v.command);return}if(f.id==='calendarForm'){let n=Number(v.count);if(!Number.isInteger(n)||n<1||n>60)return;a.calendar=n}if(f.id==='taskForm')a.tasks.push({id:crypto.randomUUID(),title:v.title.trim(),done:false});if(f.id==='noteForm'||f.id==='planForm'){let key=f.id==='noteForm'?'notes':'events',id=f.dataset.id||crypto.randomUUID(),idx=a[key].findIndex(x=>x.id===id),entry={...v,id};if(idx>=0)a[key][idx]=entry;else a[key].push(entry)}persist();$('#modal').close();render();toast('Saved in your personal workspace.')});
